begin;
insert into public.empresas(company_id,nome_fantasia) values('FAT-OWNER-QA','Ownership QA');
insert into public.licencas(company_id,status) values('FAT-OWNER-QA','ATIVA');
insert into public.modulos(company_id,modulo,status) values('FAT-OWNER-QA','gestodefaturamentoeresultado','LIBERADO');
insert into public.usuarios(company_id,login,nome,senha_hash,role,ativo) values('FAT-OWNER-QA','qa-master','Master',repeat('c',64),'MASTER',true);
insert into public.module_users(company_id,modulo,login,perfil,ativo) values('FAT-OWNER-QA','gestodefaturamentoeresultado','qa-master','MASTER',true);
insert into public.module_sessions(token,company_id,login,modulo) values(repeat('m',64),'FAT-OWNER-QA','qa-master','gestodefaturamentoeresultado');
set local role anon;
select public.faturamento_gerenciar_usuario(repeat('m',64),'CREATE','qa-manager-a','Manager A',repeat('a',64),'GESTOR',array['overview','transport','storage','costs'],true);
select public.faturamento_gerenciar_usuario(repeat('m',64),'CREATE','qa-manager-b','Manager B',repeat('b',64),'GESTOR',array['overview','transport','storage','costs'],true);
select public.faturamento_gerenciar_usuario(repeat('m',64),'CREATE','qa-master-team','Master team',repeat('d',64),'EXECUTOR',array['transport'],true);
reset role;
insert into public.module_sessions(token,company_id,login,modulo) values(repeat('a',64),'FAT-OWNER-QA','qa-manager-a','gestodefaturamentoeresultado'),(repeat('b',64),'FAT-OWNER-QA','qa-manager-b','gestodefaturamentoeresultado');
set local role anon;
select public.faturamento_gerenciar_usuario(repeat('a',64),'CREATE','qa-team-a','Team A',repeat('d',64),'VISUALIZADOR',array['transport'],true);
select public.faturamento_gerenciar_usuario(repeat('b',64),'CREATE','qa-team-b','Team B',repeat('d',64),'EXECUTOR',array['transport'],true);
do $$declare r jsonb;target text;act text;begin
 r:=public.faturamento_usuarios(repeat('a',64));assert jsonb_array_length(r->'users')=1;assert r->'users'->0->>'login'='qa-team-a';assert r->'users'->0->>'managed_by'='qa-manager-a';
 r:=public.faturamento_usuarios(repeat('b',64));assert jsonb_array_length(r->'users')=1;assert r->'users'->0->>'login'='qa-team-b';
 r:=public.faturamento_usuarios(repeat('m',64));assert jsonb_array_length(r->'users')=6;
 foreach target in array array['qa-team-b','qa-master-team','qa-manager-b','qa-master'] loop
  begin perform public.faturamento_gerenciar_usuario(repeat('a',64),'UPDATE',target,'',null,'EXECUTOR',array['transport'],true);raise exception 'Cross-team update allowed: %',target;exception when insufficient_privilege then null;end;
  begin perform public.faturamento_redefinir_senha(repeat('a',64),target,repeat('f',64));raise exception 'Cross-team reset allowed';exception when insufficient_privilege then null;end;
  foreach act in array array['BLOCK','UNBLOCK','DELETE'] loop
   begin perform public.faturamento_acao_usuario(repeat('a',64),act,target);raise exception 'Cross-team action allowed';exception when insufficient_privilege then null;end;
  end loop;
 end loop;
 begin perform public.faturamento_gerenciar_usuario(repeat('a',64),'LINK','qa-team-b','',null,'EXECUTOR',array['transport'],true);raise exception 'Manager claimed another user';exception when insufficient_privilege then null;end;
 begin perform public.faturamento_gerenciar_usuario(repeat('a',64),'CREATE','qa-team-b','Team B',repeat('d',64),'EXECUTOR',array['transport'],true);raise exception 'Manager recreated another user';exception when insufficient_privilege then null;end;
 perform public.faturamento_gerenciar_usuario(repeat('a',64),'UPDATE','qa-team-a','',null,'EXECUTOR',array['transport'],true);
 perform public.faturamento_gerenciar_usuario(repeat('m',64),'UPDATE','qa-team-a','',null,'VISUALIZADOR',array['transport'],true);
 r:=public.faturamento_usuarios(repeat('a',64));assert jsonb_array_length(r->'users')=1;assert r->'users'->0->>'managed_by'='qa-manager-a','Master update stole ownership';
 perform public.faturamento_acao_usuario(repeat('a',64),'BLOCK','qa-team-a');
 r:=public.faturamento_usuarios(repeat('a',64));assert not (r->'users'->0->>'active')::boolean;
 perform public.faturamento_acao_usuario(repeat('a',64),'UNBLOCK','qa-team-a');
 perform public.faturamento_redefinir_senha(repeat('a',64),'qa-team-a',repeat('f',64));
 perform public.faturamento_acao_usuario(repeat('m',64),'BLOCK','qa-team-b');
 perform public.faturamento_acao_usuario(repeat('m',64),'UNBLOCK','qa-team-b');
 perform public.faturamento_gerenciar_usuario(repeat('m',64),'UPDATE','qa-team-b','',null,'VISUALIZADOR',array['transport'],true);
 perform public.faturamento_redefinir_senha(repeat('m',64),'qa-team-b',repeat('f',64));
 perform public.faturamento_acao_usuario(repeat('a',64),'DELETE','qa-team-a');
 r:=public.faturamento_usuarios(repeat('a',64));assert jsonb_array_length(r->'users')=0;
 begin perform public.faturamento_gerenciar_usuario(repeat('a',64),'LINK','qa-team-a','',null,'EXECUTOR',array['transport'],true);raise exception 'Manager rebound central user';exception when insufficient_privilege then null;end;
 perform public.faturamento_gerenciar_usuario(repeat('m',64),'LINK','qa-team-a','',null,'EXECUTOR',array['transport'],true);
 r:=public.faturamento_usuarios(repeat('a',64));assert jsonb_array_length(r->'users')=0;
 perform public.faturamento_acao_usuario(repeat('m',64),'DELETE','qa-team-b');
end $$;
reset role;
rollback;
